D=/opt/course/s07-sa
SRV=$(kubectl config view --minify -o jsonpath='{.clusters[0].cluster.server}')
tk() { kubectl --kubeconfig=/dev/null --server=$SRV --certificate-authority=/etc/kubernetes/pki/ca.crt --token="$(tr -d '[:space:]' < $1)" --request-timeout=8s "${@:2}" </dev/null; }
claims() { tr -d '[:space:]' < $1 | cut -d. -f2 | tr '_-' '/+' | python3 -c 'import sys,base64,json; s=sys.stdin.read(); s+="="*(-len(s)%4); d=json.loads(base64.b64decode(s)); print(d.get("sub",""), d.get("exp",0)-d.get("iat",0))'; }
pods() { kubectl -n s07-sa get pods -l app=$1 --field-selector=status.phase=Running -o json 2>/dev/null; }
check "SA reporter can get/list pods in s07-sa (Role/RoleBinding reporter)" 'kubectl -n s07-sa get role reporter && kubectl -n s07-sa get rolebinding reporter && kubectl auth can-i list pods -n s07-sa --as=system:serviceaccount:s07-sa:reporter | grep -qx yes'
check "Secret reporter-token is a service-account-token for reporter" '[ "$(jp secret reporter-token -n s07-sa "{.type} {.metadata.annotations.kubernetes\.io/service-account\.name}")" = "kubernetes.io/service-account-token reporter" ]'
check "reporter.token is the decoded long-lived token and works" '[ -s $D/reporter.token ] && [ "$(tr -d "[:space:]" < $D/reporter.token)" = "$(jp secret reporter-token -n s07-sa "{.data.token}" | base64 -d)" ] && tk $D/reporter.token -n s07-sa get pods'
check "reporter-2h.token is a reporter token valid for 2h" '[ "$(claims $D/reporter-2h.token)" = "system:serviceaccount:s07-sa:reporter 7200" ] && tk $D/reporter-2h.token -n s07-sa get pods'
check "Secret regcred is a dockerconfigjson for registry.s07.internal:5000 (user scanner)" '[ "$(jp secret regcred -n s07-sa "{.type}")" = kubernetes.io/dockerconfigjson ] && jp secret regcred -n s07-sa "{.data.\.dockerconfigjson}" | base64 -d | python3 -c "import json,sys,base64; a=json.load(sys.stdin)[\"auths\"][\"registry.s07.internal:5000\"]; assert a.get(\"username\",\"scanner\")==\"scanner\" and base64.b64decode(a[\"auth\"]).decode()==\"scanner:Sc4nner-Pass\""'
check "SA reporter has imagePullSecret regcred" 'jp sa reporter -n s07-sa "{.imagePullSecrets[*].name}" | grep -qw regcred'
check "Deployment scanner runs as reporter, Pod has regcred injected, rolled out" '[ "$(jp deploy scanner -n s07-sa "{.spec.template.spec.serviceAccountName}")" = reporter ] && [ -z "$(jp deploy scanner -n s07-sa "{.spec.template.spec.imagePullSecrets}")" ] && kubectl -n s07-sa rollout status deploy/scanner --timeout=60s && pods scanner | python3 -c "import json,sys; p=[x for x in json.load(sys.stdin)[\"items\"] if not x[\"metadata\"].get(\"deletionTimestamp\")]; assert p and all(x[\"spec\"][\"serviceAccountName\"]==\"reporter\" and {\"name\":\"regcred\"} in x[\"spec\"].get(\"imagePullSecrets\",[]) for x in p)"'
check "SA batch-runner has automountServiceAccountToken false" '[ "$(jp sa batch-runner -n s07-sa "{.automountServiceAccountToken}")" = false ]'
check "running batch Pods have no token mounted" 'kubectl -n s07-sa rollout status deploy/batch --timeout=60s && n=$(pods batch | python3 -c "import json,sys; p=[x for x in json.load(sys.stdin)[\"items\"] if not x[\"metadata\"].get(\"deletionTimestamp\")]; print(len(p) if p and not any(\"serviceAccountToken\" in json.dumps(x[\"spec\"].get(\"volumes\",[])) for x in p) else 0)") && [ "$n" -ge 1 ] && ! kubectl -n s07-sa exec deploy/batch -- ls /var/run/secrets/kubernetes.io/serviceaccount/token'
guard "Deployment batch still uses batch-runner" '[ "$(jp deploy batch -n s07-sa "{.spec.template.spec.serviceAccountName}")" = batch-runner ]'
guard "reporter cannot delete pods" '! kubectl auth can-i delete pods -n s07-sa --as=system:serviceaccount:s07-sa:reporter | grep -qx yes'
